package app.zhijian.notes.backup;
import org.json.*;import java.io.*;import java.util.*;import java.util.zip.*;import java.util.regex.*;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;
import app.zhijian.notes.data.RecordValidator;
import org.commonmark.parser.Parser;import org.commonmark.node.AbstractVisitor;import org.commonmark.node.Image;
public final class ArchiveCodec {
 public static Set<String> noteReferences(JSONObject note){Set<String> refs=references(note.optString("content"),note.optString("mode"));addFiles(refs,note);JSONArray history=note.optJSONArray("_history");if(history!=null)for(int i=0;i<history.length();i++){JSONObject version=history.optJSONObject(i);if(version!=null){refs.addAll(references(version.optString("content"),version.optString("mode")));addFiles(refs,version);}}return refs;}
 private static void addFiles(Set<String> refs,JSONObject note){JSONArray files=note.optJSONArray("attachments");if(files!=null)for(int i=0;i<files.length();i++){JSONObject file=files.optJSONObject(i);if(file!=null&&file.optString("src").matches("media/[a-zA-Z0-9_-]+\\.bin"))refs.add(file.optString("src").substring(6));}}
 public static Set<String> references(String content){return references(content,"markdown");}
 public static Set<String> references(String content,String mode){
  Set<String> refs=new HashSet<>();
  if("rich".equals(mode)){Matcher images=Pattern.compile("<img\\b([^>]*)>",Pattern.CASE_INSENSITIVE).matcher(content);Pattern attributes=Pattern.compile("([A-Za-z_:][-A-Za-z0-9_:.]*)\\s*=\\s*(?:\"([^\"]*)\"|'([^']*)'|([^\\s>]+))");while(images.find()){Matcher a=attributes.matcher(images.group(1));while(a.find())if(a.group(1).equalsIgnoreCase("src"))addDestination(refs,a.group(2)!=null?a.group(2):a.group(3)!=null?a.group(3):a.group(4));}}
  else Parser.builder().build().parse(content).accept(new AbstractVisitor(){@Override public void visit(Image image){addDestination(refs,image.getDestination());}});
  return refs;
 }
 private static void addDestination(Set<String> refs,String src){String value=src.replaceFirst("^https://paper\\.local/","");if(value.matches("media/[a-zA-Z0-9_-]+\\.(png|jpg|jpeg|webp|gif)"))refs.add(value.substring(6));}
 public static String hash(File f)throws Exception{MessageDigest d=MessageDigest.getInstance("SHA-256");try(InputStream in=new FileInputStream(f)){byte[] buf=new byte[8192];int n;while((n=in.read(buf))!=-1)d.update(buf,0,n);}StringBuilder b=new StringBuilder();for(byte x:d.digest())b.append(String.format(Locale.ROOT,"%02x",x));return b.toString();}
 private static void copy(InputStream in,OutputStream out)throws IOException{byte[] b=new byte[16384];int n;while((n=in.read(b))!=-1)out.write(b,0,n);}
 private static void entry(ZipOutputStream z,String name,byte[] data)throws IOException{z.putNextEntry(new ZipEntry(name));z.write(data);z.closeEntry();}
 public static void write(OutputStream out,JSONObject manifest,File media)throws Exception{
  byte[] json=manifest.toString().getBytes(StandardCharsets.UTF_8);ArchivePolicy.validateEntry("manifest.json",json.length);JSONObject hashes=manifest.getJSONObject("media");if(hashes.length()+1>10000)throw new IllegalArgumentException("备份附件过多");long total=json.length;Iterator<String> check=hashes.keys();while(check.hasNext()){String name=check.next();File f=new File(media,name);ArchivePolicy.validateEntry("media/"+name,f.length());total+=f.length();if(total>ArchivePolicy.MAX_TOTAL)throw new IllegalArgumentException("备份超过 1 GB，请先分批导出笔记");}
  try(ZipOutputStream z=new ZipOutputStream(out)){entry(z,"manifest.json",json);Iterator<String> it=hashes.keys();while(it.hasNext()){String name=it.next();File f=new File(media,name);if(!f.isFile()||!hash(f).equals(hashes.getString(name)))throw new IOException("备份图片已改变，请重试");z.putNextEntry(new ZipEntry("media/"+name));try(InputStream in=new FileInputStream(f)){copy(in,z);}z.closeEntry();}}
 }
 public static JSONObject read(InputStream in,File stage)throws Exception{
  if(!stage.isDirectory()&&!stage.mkdirs())throw new IOException("无法创建恢复暂存目录");
  Set<String> seen=new HashSet<>();long total=0;
  try(ZipInputStream z=new ZipInputStream(in)){ZipEntry e;while((e=z.getNextEntry())!=null){String name=e.getName();ArchivePolicy.validateEntry(name,0);if(!seen.add(name)||seen.size()>10000)throw new IllegalArgumentException("备份包含重复文件或文件过多");File dest=new File(stage,name);if(!dest.getCanonicalPath().startsWith(stage.getCanonicalPath()+File.separator))throw new IllegalArgumentException("无效备份路径");File parent=dest.getParentFile();if(!parent.isDirectory()&&!parent.mkdirs())throw new IOException("无法创建附件目录");long size=0;try(OutputStream o=new FileOutputStream(dest)){byte[] b=new byte[16384];int n;while((n=z.read(b))!=-1){size+=n;total+=n;ArchivePolicy.validateEntry(name,size);if(total>ArchivePolicy.MAX_TOTAL)throw new IllegalArgumentException("备份解压内容过大");o.write(b,0,n);}}z.closeEntry();}}
  File mf=new File(stage,"manifest.json");if(!mf.isFile())throw new IOException("备份缺少清单");ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(InputStream f=new FileInputStream(mf)){copy(f,bytes);}JSONObject manifest=new JSONObject(bytes.toString("UTF-8"));RecordValidator.snapshot(manifest);JSONObject hashes=manifest.getJSONObject("media");Iterator<String> it=hashes.keys();Set<String> expected=new HashSet<>();expected.add("manifest.json");while(it.hasNext()){String name=it.next();ArchivePolicy.validateEntry("media/"+name,0);File f=new File(stage,"media/"+name);if(!f.isFile()||!hash(f).equals(hashes.getString(name)))throw new IOException("备份图片缺失或校验失败");expected.add("media/"+name);}if(!seen.equals(expected))throw new IOException("备份中存在未登记的文件");
  JSONArray notes=manifest.getJSONArray("notes");for(int i=0;i<notes.length();i++){JSONObject note=notes.getJSONObject(i);for(String ref:noteReferences(note))if(!hashes.has(ref))throw new IOException("笔记或历史版本引用的附件缺失");}return manifest;
 }
 public static void writeMarkdown(OutputStream out,JSONArray notes,File media)throws Exception{
  Set<String> images=new LinkedHashSet<>(),ids=new HashSet<>();Map<String,String> files=new LinkedHashMap<>();
  for(int i=0;i<notes.length();i++){String id=notes.getJSONObject(i).getString("id");if(!id.matches("[a-zA-Z0-9-]+")||!ids.add(id))throw new IllegalArgumentException("导出记录 ID 无效");}
  try(ZipOutputStream z=new ZipOutputStream(out)){for(int i=0;i<notes.length();i++){JSONObject n=notes.getJSONObject(i);String id=n.getString("id"),md=n.getString("markdown");Matcher links=Pattern.compile("paper-note:([a-fA-F0-9-]{36})").matcher(md);StringBuffer linked=new StringBuffer();while(links.find()){String target=links.group(1);links.appendReplacement(linked,Matcher.quoteReplacement(ids.contains(target)?target+".md":links.group()));}links.appendTail(linked);md=linked.toString();JSONArray attachments=n.optJSONArray("attachments");if(attachments!=null)for(int j=0;j<attachments.length();j++){JSONObject file=attachments.getJSONObject(j);String src=file.getString("src");if(!src.matches("media/[a-zA-Z0-9_-]+\\.bin"))throw new IllegalArgumentException("导出附件路径无效");String name=src.substring(6),friendly=file.optString("name","附件").replaceAll("[\\\\/:*?\"<>|\\p{Cntrl}]","_");if(friendly.length()>160)friendly=friendly.substring(friendly.length()-160);String destination="files/"+name.substring(0,name.length()-4)+"-"+friendly;files.put(name,destination);md+="\n\n["+friendly.replace("[","_").replace("]","_")+"]("+destination.replace("%","%25").replace(" ","%20").replace("#","%23").replace("?","%3F").replace("(","%28").replace(")","%29").replace("[","%5B").replace("]","%5D")+")";}images.addAll(references(md,"markdown"));String title=n.optString("title","无标题").replace('\n',' ').replace('\r',' ');entry(z,id+".md",("# "+title+"\n\n"+md+"\n").getBytes(StandardCharsets.UTF_8));}
   images.addAll(files.keySet());for(String name:images){File f=new File(media,name);if(!f.isFile())throw new IOException("导出附件缺失，请检查原笔记");z.putNextEntry(new ZipEntry(files.containsKey(name)?files.get(name):"media/"+name));try(InputStream input=new FileInputStream(f)){copy(input,z);}z.closeEntry();}
  }
 }
}
